require_once '../config.php'; header('Content-Type: application/json; charset=utf-8'); $userId=requireAuth();
$in=json_decode(file_get_contents('php://input'),true)?:[];$id=intval($in['idea_id']??0);$day=max(1,intval($in['current_day']??1));$progress=mb_substr(trim((string)($in['progress']??'')),0,8000);
if(!$id){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Ideia inválida.']);exit;}
try{$db=getDBConnection();$q=$db->prepare('SELECT title,content,category FROM ideas WHERE id=? AND user_id=?');$q->execute([$id,$userId]);$idea=$q->fetch();if(!$idea){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Ideia não encontrada.']);exit;}$prompt="Tu és o Edify, um coach de execução prático, caloroso e direto. Ajuda o utilizador a executar a ideia abaixo.\nIDEIA: {$idea['title']}\nCATEGORIA: {$idea['category']}\nPLANO: ".mb_substr(strip_tags($idea['content']),0,16000)."\nDIA ATUAL: $day\nPROGRESSO REGISTADO: $progress\nResponde em português de Portugal, como uma fala curta de 60 a 100 palavras, começando por uma saudação breve. Diz exatamente o que fazer agora em 2 ou 3 passos concretos, uma coisa que deve ficar concluída hoje e termina com uma pergunta simples para o utilizador confirmar o progresso. Não uses markdown, emojis, URLs nem listas com marcadores.";$r=callGeminiAPI($prompt);$message=trim($r['choices'][0]['message']['content']??'');if(!$message){http_response_code(502);echo json_encode(['success'=>false,'message'=>'O Edify não conseguiu preparar a orientação.']);exit;}echo json_encode(['success'=>true,'message'=>$message,'day'=>$day],JSON_UNESCAPED_UNICODE);}catch(Exception $e){error_log('Erro plan-coach: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Não foi possível obter a orientação do Edify.']);}
